    15→package org.hyperledger.besu.evm.precompile;
    16→
    17→import org.hyperledger.besu.crypto.SECP256R1;
    18→import org.hyperledger.besu.crypto.SECPPublicKey;
    19→import org.hyperledger.besu.crypto.SECPSignature;
    20→import org.hyperledger.besu.crypto.SignatureAlgorithm;
    21→import org.hyperledger.besu.evm.frame.MessageFrame;
    22→import org.hyperledger.besu.evm.gascalculator.GasCalculator;
    23→import org.hyperledger.besu.nativelib.boringssl.BoringSSLPrecompiles;
    24→
    25→import java.math.BigInteger;
    26→
    27→import com.github.benmanes.caffeine.cache.Cache;
    28→import com.github.benmanes.caffeine.cache.Caffeine;
    29→import jakarta.validation.constraints.NotNull;
    30→import org.apache.tuweni.bytes.Bytes;
    31→import org.apache.tuweni.bytes.Bytes32;
    32→import org.bouncycastle.asn1.sec.SECNamedCurves;
    33→import org.bouncycastle.asn1.x9.X9ECParameters;
    34→import org.slf4j.Logger;
    35→import org.slf4j.LoggerFactory;
    36→
    37→/** Implementation of EIP-7951. */
    38→public class P256VerifyPrecompiledContract extends AbstractPrecompiledContract {
    39→  private static final Logger LOG = LoggerFactory.getLogger(P256VerifyPrecompiledContract.class);
    40→  private static final String PRECOMPILE_NAME = "P256VERIFY";
    41→  private static final Bytes32 VALID = Bytes32.leftPad(Bytes.of(1), (byte) 0);
    42→  private static final Bytes INVALID = Bytes.EMPTY;
    43→  private static final int SECP256R1_INPUT_LENGTH = 160;
    44→
    45→  static final X9ECParameters R1_PARAMS = SECNamedCurves.getByName("secp256r1");
    46→  static final BigInteger N = R1_PARAMS.getN();
    47→  static final BigInteger P = R1_PARAMS.getCurve().getField().getCharacteristic();
    48→
    49→  /** The constant useNative. */
    50→  // use the BoringSSL native library implementation, if it is available
    51→  private static boolean useNativeBoringSSL;
    52→
    53→  static {
    54→    maybeEnableNativeBoringSSL();
    55→  }
    56→
    57→  /**
    58→   * Attempt to enable the BoringSSL native library for P256Verify contract Note, if BoringSSL is
    59→   * disabled, then native SECP256R1 may still be enabled
    60→   *
    61→   * @return true if the native library was enabled.
    62→   */
    63→  public static boolean maybeEnableNativeBoringSSL() {
    64→    try {
    65→      useNativeBoringSSL = BoringSSLPrecompiles.ENABLED;
    66→    } catch (UnsatisfiedLinkError | NoClassDefFoundError ule) {
    67→      LOG.info(
    68→          "BoringSSL secp256r1 p256verify native precompile not available: {}", ule.getMessage());
    69→      useNativeBoringSSL = false;
    70→    }
    71→    return useNativeBoringSSL;
    72→  }
    73→
    74→  /** Disable native. Note SECP256R1 must additionally be disabled to fully disable native */
    75→  public static void disableNativeBoringSSL() {
    76→    useNativeBoringSSL = false;
    77→  }
    78→
    79→  /**
    80→   * Is native BoringSSL boolean.
    81→   *
    82→   * @return the boolean indicating whether to use the BoringSSL native library implementation, if
    83→   *     it is available
    84→   */
    85→  public static boolean isNativeBoringSSL() {
    86→    return useNativeBoringSSL;
    87→  }
    88→
    89→  private final GasCalculator gasCalculator;
    90→  private final SignatureAlgorithm signatureAlgorithm;
    91→
    92→  private static final Cache<Integer, PrecompileInputResultTuple> p256VerifyCache =
    93→      Caffeine.newBuilder().maximumSize(1000).build();
    94→
    95→  /**
    96→   * Instantiates a new Abstract precompiled contract.
    97→   *
    98→   * @param gasCalculator the gas calculator
    99→   */
   100→  public P256VerifyPrecompiledContract(final GasCalculator gasCalculator) {
   101→    this(gasCalculator, new SECP256R1());
   102→  }
   103→
   104→  /**
   105→   * Instantiates a new Abstract precompiled contract.
   106→   *
   107→   * @param gasCalculator the gas calculator
   108→   * @param signatureAlgorithm the signature algorithm to use
   109→   */
   110→  public P256VerifyPrecompiledContract(
   111→      final GasCalculator gasCalculator, final SignatureAlgorithm signatureAlgorithm) {
   112→    super(PRECOMPILE_NAME, gasCalculator);
   113→    this.gasCalculator = gasCalculator;
   114→    this.signatureAlgorithm = signatureAlgorithm;
   115→  }
   116→
   117→  @Override
   118→  public long gasRequirement(final Bytes input) {
   119→    return gasCalculator.getP256VerifyPrecompiledContractGasCost();
   120→  }
   121→
   122→  @Override
   123→  public PrecompileContractResult computePrecompile(
   124→      final Bytes input, final MessageFrame messageFrame) {
   125→    if (input.size() != SECP256R1_INPUT_LENGTH) {
   126→      LOG.warn(
   127→          "Invalid input length for P256VERIFY precompile: expected {} bytes but got {}",
   128→          SECP256R1_INPUT_LENGTH,
   129→          input.size());
   130→      return PrecompileContractResult.success(INVALID);
   131→    }
   132→    PrecompileInputResultTuple res = null;
   133→    Integer cacheKey = null;
   134→    if (enableResultCaching) {
   135→      cacheKey = getCacheKey(input);
   136→      res = p256VerifyCache.getIfPresent(cacheKey);
   137→
   138→      if (res != null) {
   139→        if (res.cachedInput().equals(input)) {
   140→          cacheEventConsumer.accept(new CacheEvent(PRECOMPILE_NAME, CacheMetric.HIT));
   141→          return res.cachedResult();
   142→        } else {
   143→          LOG.debug(
   144→              "false positive p256verify {}, cache key {}, cached input: {}, input: {}",
   145→              input.getClass().getSimpleName(),
   146→              cacheKey,
   147→              res.cachedInput().toHexString(),
   148→              input.toHexString());
   149→          cacheEventConsumer.accept(new CacheEvent(PRECOMPILE_NAME, CacheMetric.FALSE_POSITIVE));
   150→        }
   151→      } else {
   152→        cacheEventConsumer.accept(new CacheEvent(PRECOMPILE_NAME, CacheMetric.MISS));
   153→      }
   154→    }
   155→
   156→    try {
   157→      if (useNativeBoringSSL) {
   158→        res = computeNative(input);
   159→      } else {
   160→        res = computeDefault(input);
   161→      }
   162→
   163→      if (enableResultCaching) {
   164→        p256VerifyCache.put(cacheKey, res);
   165→      }
   166→      return res.cachedResult();
   167→
   168→    } catch (Exception e) {
   169→      LOG.warn("P256VERIFY verification failed: {}", e.getMessage());
   170→      System.err.println("P256VERIFY verification failed: " + e.getMessage());
   171→      return PrecompileContractResult.success(INVALID);
   172→    }
   173→  }
   174→
   175→  @NotNull
   176→  private static PrecompileInputResultTuple computeNative(final Bytes input) {
   177→    PrecompileInputResultTuple res;
   178→    BoringSSLPrecompiles.P256VerifyResult result =
   179→        BoringSSLPrecompiles.p256Verify(input.toArrayUnsafe(), input.size());
   180→
   181→    if (result.status != 0) {
   182→      LOG.atTrace().setMessage("Verify failed: {}").addArgument(result.error).log();
   183→    }
   184→    res =
   185→        new PrecompileInputResultTuple(
   186→            enableResultCaching ? input.copy() : input,
   187→            PrecompileContractResult.success(result.status == 0 ? VALID : INVALID));
   188→    return res;
   189→  }
   190→
   191→  // This may still use native SECP256R1 depending on how SignatureAlgorithm is configured
   192→  @NotNull
   193→  PrecompileInputResultTuple computeDefault(final Bytes input) {
   194→    final Bytes messageHash = input.slice(0, 32);
   195→    final Bytes rBytes = input.slice(32, 32);
   196→    final Bytes sBytes = input.slice(64, 32);
   197→    final Bytes pubKeyBytes = input.slice(96, 64);
   198→    final BigInteger qx = pubKeyBytes.slice(0, 32).toUnsignedBigInteger();
   199→    final BigInteger qy = pubKeyBytes.slice(32, 32).toUnsignedBigInteger();
   200→
   201→    // Convert r and s to BigIntegers (unsigned)
   202→    final BigInteger r = rBytes.toUnsignedBigInteger();
   203→    final BigInteger s = sBytes.toUnsignedBigInteger();
   204→
   205→    // Check r, s in (0, n)
   206→    if (r.signum() <= 0 || r.compareTo(N) >= 0 || s.signum() <= 0 || s.compareTo(N) >= 0) {
   207→      LOG.trace("Invalid r or s: must satisfy 0 < r,s < n");
   208→      return new PrecompileInputResultTuple(
   209→          enableResultCaching ? input.copy() : input, PrecompileContractResult.success(INVALID));
   210→    }
   211→
   212→    // Check qx, qy in [0, p)
   213→    if (qx.signum() < 0 || qx.compareTo(P) >= 0 || qy.signum() < 0 || qy.compareTo(P) >= 0) {
   214→      LOG.trace("Invalid qx or qy: must satisfy 0 <= qx,qy < p");
   215→      return new PrecompileInputResultTuple(
   216→          enableResultCaching ? input.copy() : input, PrecompileContractResult.success(INVALID));
   217→    }
   218→
   219→    // Check point not at infinity (qx, qy ≠ 0,0), and non-trivial infinity encoding
   220→    if ((qx.signum() == 0 && qy.signum() == 0)) {
   221→      LOG.trace("Invalid public key: point at infinity");
   222→      return new PrecompileInputResultTuple(
   223→          enableResultCaching ? input.copy() : input, PrecompileContractResult.success(INVALID));
   224→    }
   225→    try {
   226→      final org.bouncycastle.math.ec.ECPoint ecPoint = R1_PARAMS.getCurve().createPoint(qx, qy);
   227→      signatureAlgorithm.getCurve().validatePublicPoint(ecPoint);
   228→    } catch (IllegalArgumentException e) {
   229→      LOG.trace("Public key not on curve: {}", e.getMessage());
   230→      return new PrecompileInputResultTuple(
   231→          enableResultCaching ? input.copy() : input, PrecompileContractResult.success(INVALID));
   232→    }
   233→    // Create the signature; recID is not used in verification - use 0
   234→    final SECPSignature signature = signatureAlgorithm.createSignature(r, s, (byte) 0);
   235→    final SECPPublicKey publicKey = signatureAlgorithm.createPublicKey(pubKeyBytes);
   236→
   237→    final boolean isValid = signatureAlgorithm.verifyMalleable(messageHash, signature, publicKey);
   238→
   239→    return new PrecompileInputResultTuple(
   240→        enableResultCaching ? input.copy() : input,
   241→        PrecompileContractResult.success(isValid ? VALID : INVALID));
   242→  }
   243→}
