    15→package org.hyperledger.besu.evm.precompile;
    16→
    17→import static org.hyperledger.besu.datatypes.Address.P256_VERIFY;
    18→
    19→import org.hyperledger.besu.datatypes.Address;
    20→import org.hyperledger.besu.evm.gascalculator.GasCalculator;
    21→
    22→/** Provides the various precompiled contracts used on mainnet hard forks. */
    23→public interface MainnetPrecompiledContracts {
    24→
    25→  /**
    26→   * Frontier precompile contract registry.
    27→   *
    28→   * @param gasCalculator the gas calculator
    29→   * @return the precompile contract registry
    30→   */
    31→  static PrecompileContractRegistry frontier(final GasCalculator gasCalculator) {
    32→    PrecompileContractRegistry precompileContractRegistry = new PrecompileContractRegistry();
    33→    populateForFrontier(precompileContractRegistry, gasCalculator);
    34→    return precompileContractRegistry;
    35→  }
    36→
    37→  /**
    38→   * Populate registry for frontier.
    39→   *
    40→   * @param registry the registry
    41→   * @param gasCalculator the gas calculator
    42→   */
    43→  static void populateForFrontier(
    44→      final PrecompileContractRegistry registry, final GasCalculator gasCalculator) {
    45→    registry.put(Address.ECREC, new ECRECPrecompiledContract(gasCalculator));
    46→    registry.put(Address.SHA256, new SHA256PrecompiledContract(gasCalculator));
    47→    registry.put(Address.RIPEMD160, new RIPEMD160PrecompiledContract(gasCalculator));
    48→    registry.put(Address.ID, new IDPrecompiledContract(gasCalculator));
    49→  }
    50→
    51→  /**
    52→   * Homestead precompile contract registry.
    53→   *
    54→   * @param gasCalculator the gas calculator
    55→   * @return the precompile contract registry
    56→   */
    57→  static PrecompileContractRegistry homestead(final GasCalculator gasCalculator) {
    58→    return frontier(gasCalculator);
    59→  }
    60→
    61→  /**
    62→   * Byzantium precompile contract registry.
    63→   *
    64→   * @param gasCalculator the gas calculator
    65→   * @return the precompile contract registry
    66→   */
    67→  static PrecompileContractRegistry byzantium(final GasCalculator gasCalculator) {
    68→    PrecompileContractRegistry precompileContractRegistry = new PrecompileContractRegistry();
    69→    populateForByzantium(precompileContractRegistry, gasCalculator);
    70→    return precompileContractRegistry;
    71→  }
    72→
    73→  /**
