    38→public class SECP256R1AcceptanceTest extends AcceptanceTestBase {
    39→  private Node minerNode;
    40→  private Node otherNode;
    41→  private Cluster noDiscoveryCluster;
    42→
    43→  private static final String GENESIS_FILE = "/crypto/secp256r1.json";
    44→
    45→  private static final String MINER_NODE_PRIVATE_KEY =
    46→      "8f2a55949038a9610f50fb23b5883af3b4ecb3c3bb792cbcefbd1542c692be63";
    47→  private static final String OTHER_NODE_PRIVATE_KEY =
    48→      "c87509a1c067bbde78beb793e6fa76530b6382a4c0241e5e4a9ec0a0f44dc0d3";
    49→
    50→  private static final SECP256R1 SECP256R1_SIGNATURE_ALGORITHM = new SECP256R1();
    51→
    52→  @BeforeEach
    53→  public void setUp() throws Exception {
    54→    KeyPair minerNodeKeyPair = createKeyPair(MINER_NODE_PRIVATE_KEY);
    55→    KeyPair otherNodeKeyPair = createKeyPair(OTHER_NODE_PRIVATE_KEY);
    56→
    57→    final ClusterConfiguration clusterConfiguration =
    58→        new ClusterConfigurationBuilder().awaitPeerDiscovery(false).build();
    59→    noDiscoveryCluster = new Cluster(clusterConfiguration, net);
    60→
    61→    minerNode =
    62→        besu.createNodeWithNonDefaultSignatureAlgorithm(
    63→            "minerNode", GENESIS_FILE, minerNodeKeyPair, List.of());
    64→    noDiscoveryCluster.start(minerNode);
    65→
    66→    otherNode =
    67→        besu.createNodeWithNonDefaultSignatureAlgorithm(
    68→            "otherNode", GENESIS_FILE, otherNodeKeyPair, List.of(minerNode));
    69→    noDiscoveryCluster.addNode(otherNode);
    70→
    71→    minerNode.verify(net.awaitPeerCount(1));
    72→    otherNode.verify(net.awaitPeerCount(1));
    73→
    74→    final var minerChainHead = minerNode.execute(ethTransactions.block());
    75→    otherNode.verify(blockchain.minimumHeight(minerChainHead.getNumber().longValue()));
    76→  }
    77→
    78→  @Test
    79→  public void transactionShouldBeSuccessful() {
    80→    // SignatureAlgorithmFactory.instance is static. When ThreadBesuRunner is used, we cannot change
    81→    // the signature algorithm instance to SECP256R1 as it could influence other tests running at
    82→    // the same time. So we only execute the test when ProcessBesuNodeRunner is used, as there is
    83→    // not conflict because we use separate processes.
    84→    assumeTrue(BesuNodeRunner.isProcessBesuNodeRunner());
    85→
    86→    minerNode.verify(net.awaitPeerCount(1));
    87→    otherNode.verify(net.awaitPeerCount(1));
    88→
    89→    final Account recipient = accounts.createAccount("recipient");
    90→
    91→    final Hash transactionHash =
    92→        minerNode.execute(accountTransactions.createTransfer(recipient, 5, new SECP256R1()));
    93→    assertThat(transactionHash).isNotNull();
    94→    noDiscoveryCluster.verify(recipient.balanceEquals(5));
    95→  }
    96→
    97→  @AfterEach
    98→  @Override
    99→  public void tearDownAcceptanceTestBase() {
   100→    super.tearDownAcceptanceTestBase();
   101→
   102→    noDiscoveryCluster.stop();
   103→  }
   104→
   105→  private KeyPair createKeyPair(final String privateKey) {
   106→    return SECP256R1_SIGNATURE_ALGORITHM.createKeyPair(
   107→        SECP256R1_SIGNATURE_ALGORITHM.createPrivateKey(Bytes32.fromHexString(privateKey)));
   108→  }
   109→}
