    29→/**
    30→ * Processes and stores historical block hashes in accordance with EIP-2935. This class is
    31→ * responsible for managing the storage of block hashes to support EIP-2935, which introduces
    32→ * historical block hash access in smart contracts.
    33→ */
    34→public class PraguePreExecutionProcessor extends CancunPreExecutionProcessor {
    35→  private static final Logger LOG = LoggerFactory.getLogger(PraguePreExecutionProcessor.class);
    36→
    37→  private static final Address HISTORY_STORAGE_ADDRESS =
    38→      Address.fromHexString("0x0000f90827f1c53a10cb7a02335b175320002935");
    39→
    40→  protected final Address historyStorageAddress;
    41→
    42→  /** Constructs a PraguePreExecutionProcessor. */
    43→  public PraguePreExecutionProcessor() {
    44→    this(HISTORY_STORAGE_ADDRESS);
    45→  }
    46→
    47→  /**
    48→   * Constructs a PraguePreExecutionProcessor with a specified history save window. This constructor
    49→   * is primarily used for testing.
    50→   *
    51→   * @param historyStorageAddress the address of the contract storing the history
    52→   */
    53→  @VisibleForTesting
    54→  public PraguePreExecutionProcessor(final Address historyStorageAddress) {
    55→    this.historyStorageAddress = historyStorageAddress;
    56→  }
    57→
    58→  @Override
    59→  public Void process(final BlockProcessingContext context) {
    60→    super.process(context);
    61→    SystemCallProcessor processor =
    62→        new SystemCallProcessor(context.getProtocolSpec().getTransactionProcessor());
    63→
    64→    Bytes inputData = context.getBlockHeader().getParentHash();
    65→    try {
    66→      processor.process(historyStorageAddress, context, inputData);
    67→    } catch (InvalidSystemCallAddressException e) {
    68→      // According to EIP-2935, the system call should fail silently if no code exists at the
    69→      // contract address
    70→      LOG.warn("Invalid system call address: {}", historyStorageAddress);
    71→    }
    72→    return null;
    73→  }
    74→
    75→  @Override
    76→  public Optional<Address> getHistoryContract() {
    77→    return Optional.of(historyStorageAddress);
    78→  }
    79→}
