    16→
    17→import static org.hyperledger.besu.datatypes.Address.BLS12_MAP_FP2_TO_G2;
    18→import static org.hyperledger.besu.evm.internal.Words.clampedAdd;
    19→import static org.hyperledger.besu.evm.worldstate.CodeDelegationHelper.hasCodeDelegation;
    20→
    21→import org.hyperledger.besu.datatypes.Address;
    22→import org.hyperledger.besu.datatypes.CodeDelegation;
    23→import org.hyperledger.besu.datatypes.Hash;
    24→import org.hyperledger.besu.datatypes.Transaction;
    25→import org.hyperledger.besu.evm.account.Account;
    26→import org.hyperledger.besu.evm.frame.MessageFrame;
    27→import org.hyperledger.besu.evm.worldstate.CodeDelegationHelper;
    28→
    29→import org.apache.tuweni.bytes.Bytes;
    30→
    31→/**
    32→ * Gas Calculator for Prague
    33→ *
    34→ * <UL>
    35→ *   <LI>Gas costs for EIP-7702 (Code Delegation)
    36→ * </UL>
    37→ */
    38→public class PragueGasCalculator extends CancunGasCalculator {
    39→  private static final long TOTAL_COST_FLOOR_PER_TOKEN = 10L;
    40→
    41→  final long existingAccountGasRefund;
    42→
    43→  /** Instantiates a new Prague Gas Calculator. */
    44→  public PragueGasCalculator() {
    45→    this(BLS12_MAP_FP2_TO_G2.toArrayUnsafe()[19]);
    46→  }
    47→
    48→  /**
    49→   * Instantiates a new Prague Gas Calculator
    50→   *
    51→   * @param maxPrecompile the max precompile
    52→   */
    53→  protected PragueGasCalculator(final int maxPrecompile) {
    54→    super(maxPrecompile);
    55→    this.existingAccountGasRefund = newAccountGasCost() - CodeDelegation.PER_AUTH_BASE_COST;
    56→  }
    57→
    58→  @Override
    59→  public long delegateCodeGasCost(final int delegateCodeListLength) {
    60→    return newAccountGasCost() * delegateCodeListLength;
    61→  }
    62→
    63→  @Override
    64→  public long calculateDelegateCodeGasRefund(final long alreadyExistingAccounts) {
    65→    return existingAccountGasRefund * alreadyExistingAccounts;
    66→  }
    67→
    68→  @Override
    69→  public long calculateGasRefund(
    70→      final Transaction transaction,
    71→      final MessageFrame initialFrame,
    72→      final long codeDelegationRefund) {
    73→
    74→    final long refundAllowance =
    75→        calculateRefundAllowance(transaction, initialFrame, codeDelegationRefund);
    76→
    77→    final long executionGasUsed =
    78→        transaction.getGasLimit() - initialFrame.getRemainingGas() - refundAllowance;
    79→    final long transactionFloorCost =
    80→        transactionFloorCost(transaction.getPayload(), transaction.getPayloadZeroBytes());
    81→    final long totalGasUsed = Math.max(executionGasUsed, transactionFloorCost);
    82→    return transaction.getGasLimit() - totalGasUsed;
    83→  }
    84→
    85→  private long calculateRefundAllowance(
    86→      final Transaction transaction,
    87→      final MessageFrame initialFrame,
    88→      final long codeDelegationRefund) {
    89→    final long selfDestructRefund =
    90→        getSelfDestructRefundAmount() * initialFrame.getSelfDestructs().size();
    91→    final long executionRefund =
    92→        initialFrame.getGasRefund() + selfDestructRefund + codeDelegationRefund;
    93→    // Integer truncation takes care of the floor calculation needed after the divide.
    94→    final long maxRefundAllowance =
    95→        (transaction.getGasLimit() - initialFrame.getRemainingGas()) / getMaxRefundQuotient();
    96→    return Math.min(executionRefund, maxRefundAllowance);
    97→  }
    98→
    99→  @Override
   100→  public long transactionFloorCost(final Bytes transactionPayload, final long payloadZeroBytes) {
   101→    return clampedAdd(
   102→        getMinimumTransactionCost(),
   103→        tokensInCallData(transactionPayload.size(), payloadZeroBytes) * TOTAL_COST_FLOOR_PER_TOKEN);
   104→  }
   105→
   106→  private long tokensInCallData(final long payloadSize, final long zeroBytes) {
   107→    // as defined in https://eips.ethereum.org/EIPS/eip-7623#specification
   108→    return clampedAdd(zeroBytes, (payloadSize - zeroBytes) * 4);
   109→  }
   110→
   111→  @Override
   112→  public long calculateCodeDelegationResolutionGas(
   113→      final MessageFrame frame, final Account targetAccount) {
   114→    if (targetAccount == null) {
   115→      return 0;
   116→    }
   117→
   118→    final Hash codeHash = targetAccount.getCodeHash();
   119→    if (codeHash == null || codeHash.equals(Hash.EMPTY)) {
   120→      return 0;
   121→    }
   122→
   123→    if (!hasCodeDelegation(targetAccount.getCode())) {
   124→      return 0;
   125→    }
   126→
   127→    final Address targetAddress = CodeDelegationHelper.getTargetAddress(targetAccount.getCode());
   128→
   129→    final boolean isWarm = isPrecompile(targetAddress) || frame.warmUpAddress(targetAddress);
   130→    return isWarm ? getWarmStorageReadCost() : getColdAccountAccessCost();
   131→  }
   132→}
