    16→
    17→import org.hyperledger.besu.datatypes.BlobType;
    18→
    19→import java.util.ArrayList;
    20→import java.util.List;
    21→import java.util.stream.Collectors;
    22→
    23→import ethereum.ckzg4844.CKZG4844JNI;
    24→import ethereum.ckzg4844.CellsAndProofs;
    25→import org.apache.tuweni.bytes.Bytes;
    26→import org.apache.tuweni.bytes.Bytes48;
    27→
    28→/**
    29→ * Utility class for handling KZG-related operations, including converting BlobsWithCommitments to
    30→ * version 1, extracting KZG proofs, and verifying KZG proofs.
    31→ *
    32→ * <p>Wrapper for CKZG4844JNI to provide a higher-level API for KZG operations.
    33→ */
    34→public class CKZG4844Helper {
    35→
    36→  /** Number of cell proofs per blob. */
    37→  public static final int CELL_PROOFS_PER_BLOB = 128;
    38→
    39→  /**
    40→   * Converts the given BlobsWithCommitments to version 1.
    41→   *
    42→   * @param blobsWithCommitments the BlobsWithCommitments to convert.
    43→   * @return a new BlobsWithCommitments instance with version 1 and updated proofs.
    44→   * @throws IllegalArgumentException if the blobs with commitments are not valid for conversion.
    45→   */
    46→  public static BlobsWithCommitments convertToVersion1(
    47→      final BlobsWithCommitments blobsWithCommitments) {
    48→    if (blobsWithCommitments.getBlobType() == BlobType.KZG_CELL_PROOFS) {
    49→      return blobsWithCommitments;
    50→    }
    51→    // Check if the blobs with commitments are valid for conversion
    52→    boolean isValidBlobsWithCommitments = verify4844Kzg(blobsWithCommitments);
    53→    if (!isValidBlobsWithCommitments) {
    54→      throw new IllegalArgumentException(
    55→          "Invalid blobs with commitments for conversion to version 1");
    56→    }
    57→
    58→    List<BlobProofBundle> version1Bundles =
    59→        blobsWithCommitments.getBlobProofBundles().stream()
    60→            .map(CKZG4844Helper::unsafeConvertToVersion1)
    61→            .collect(Collectors.toList());
    62→
    63→    return new BlobsWithCommitments(version1Bundles);
    64→  }
    65→
    66→  /**
    67→   * Extracts KZG proofs from the given byte array.
    68→   *
    69→   * @param input the byte array containing KZG proofs.
    70→   * @return a list of KZGProof objects extracted from the input.
    71→   */
    72→  private static List<KZGProof> extractKZGProofs(final byte[] input) {
    73→    List<KZGProof> proofs = new ArrayList<>(CELL_PROOFS_PER_BLOB);
    74→    int proofSize = KZGProof.SIZE;
    75→    for (int i = 0; i < CELL_PROOFS_PER_BLOB; i++) {
    76→      byte[] proof = new byte[proofSize];
    77→      System.arraycopy(input, i * proofSize, proof, 0, proofSize);
    78→      proofs.add(new KZGProof(Bytes48.wrap(proof)));
    79→    }
    80→    return proofs;
    81→  }
    82→
    83→  /**
    84→   * Converts the given BlobProofBundle to version 1 without validating proof.
    85→   *
    86→   * @param bundle the BlobProofBundle to convert.
    87→   * @return a new BlobProofBundle instance with version 1 and updated proofs.
    88→   */
    89→  public static BlobProofBundle unsafeConvertToVersion1(final BlobProofBundle bundle) {
    90→    if (bundle.getBlobType() == BlobType.KZG_CELL_PROOFS) {
    91→      return bundle;
    92→    }
    93→    List<KZGProof> kzgCellProofs = computeBlobKzgProofs(bundle.getBlob());
    94→    return new BlobProofBundle(
    95→        BlobType.KZG_CELL_PROOFS,
    96→        bundle.getBlob(),
    97→        bundle.getKzgCommitment(),
    98→        kzgCellProofs,
    99→        bundle.getVersionedHash());
   100→  }

