    32→import org.bouncycastle.asn1.x9.X9ECParameters;
    33→import org.bouncycastle.asn1.x9.X9IntegerConverter;
    34→import org.bouncycastle.crypto.agreement.ECDHBasicAgreement;
    35→import org.bouncycastle.crypto.params.ECDomainParameters;
    36→import org.bouncycastle.crypto.params.ECPrivateKeyParameters;
    37→import org.bouncycastle.crypto.params.ECPublicKeyParameters;
    38→import org.bouncycastle.crypto.signers.DSAKCalculator;
    39→import org.bouncycastle.crypto.signers.ECDSASigner;
    40→import org.bouncycastle.jcajce.provider.asymmetric.ec.KeyPairGeneratorSpi;
    41→import org.bouncycastle.jce.provider.BouncyCastleProvider;
    42→import org.bouncycastle.math.ec.ECAlgorithms;
    43→import org.bouncycastle.math.ec.ECPoint;
    44→
    45→/** The Abstract secp256. */
    46→public abstract class AbstractSECP256 implements SignatureAlgorithm {
    47→
    48→  /** The constant PROVIDER. */
    49→  public static final String PROVIDER = "BC";
    50→
    51→  /** The Curve. */
    52→  protected final ECDomainParameters curve;
    53→
    54→  /** The Half curve order. */
    55→  protected final BigInteger halfCurveOrder;
    56→
    57→  /** The Key pair generator. */
    58→  protected final KeyPairGenerator keyPairGenerator;
    59→
    60→  /** The Curve order. */
    61→  protected final BigInteger curveOrder;
    62→
    63→  /** The Prime. */
    64→  final BigInteger prime;
    65→
    66→  /**
    67→   * Instantiates a new Abstract secp 256.
    68→   *
    69→   * @param curveName the curve name
    70→   * @param prime the prime
    71→   */
    72→  protected AbstractSECP256(final String curveName, final BigInteger prime) {
    73→    this.prime = prime;
    74→    Security.addProvider(new BouncyCastleProvider());
    75→
    76→    final X9ECParameters params = SECNamedCurves.getByName(curveName);
    77→    curve = new ECDomainParameters(params.getCurve(), params.getG(), params.getN(), params.getH());
    78→    curveOrder = curve.getN();
    79→    halfCurveOrder = curveOrder.shiftRight(1);
    80→    try {
    81→      keyPairGenerator = new KeyPairGeneratorSpi.ECDSA();
    82→    } catch (final Exception e) {
    83→      throw new RuntimeException(e);
    84→    }
    85→    final ECGenParameterSpec ecGenParameterSpec = new ECGenParameterSpec(curveName);
    86→    try {
    87→      keyPairGenerator.initialize(ecGenParameterSpec, SecureRandomProvider.createSecureRandom());
    88→    } catch (final InvalidAlgorithmParameterException e) {
    89→      throw new RuntimeException(e);
    90→    }
    91→  }
    92→
    93→  @Override
    94→  public SECPSignature normaliseSignature(
    95→      final BigInteger nativeR,
    96→      final BigInteger nativeS,
    97→      final SECPPublicKey publicKey,
    98→      final Bytes32 dataHash) {
    99→
   100→    BigInteger s = nativeS;
   101→    // Automatically adjust the S component to be less than or equal to half the curve
   102→    // order, if necessary. This is required because for every signature (r,s) the signature
   103→    // (r, -s (mod N)) is a valid signature of the same message. However, we dislike the
   104→    // ability to modify the bits of a Bitcoin transaction after it's been signed, as that
   105→    // violates various assumed invariants. Thus in future only one of those forms will be
   106→    // considered legal and the other will be banned.
   107→    if (s.compareTo(halfCurveOrder) > 0) {
   108→      // The order of the curve is the number of valid points that exist on that curve.
   109→      // If S is in the upper half of the number of valid points, then bring it back to
   110→      // the lower half. Otherwise, imagine that
   111→      // N = 10
   112→      // s = 8, so (-8 % 10 == 2) thus both (r, 8) and (r, 2) are valid solutions.
   113→      // 10 - 8 == 2, giving us always the latter solution, which is canonical.
   114→      s = curve.getN().subtract(s);
   115→    }
   116→
   117→    // Now we have to work backwards to figure out the recId needed to recover the signature.
   118→    int recId = -1;
   119→    final BigInteger publicKeyBI = publicKey.getEncodedBytes().toUnsignedBigInteger();
   120→    for (int i = 0; i < 4; i++) {
   121→      final BigInteger k = recoverFromSignature(i, nativeR, s, dataHash);
   122→      if (k != null && k.equals(publicKeyBI)) {
   123→        recId = i;
   124→        break;
   125→      }
   126→    }
   127→    if (recId == -1) {
   128→      throw new RuntimeException(
   129→          "Could not construct a recoverable key. This should never happen.");
   130→    }
   131→
   132→    return new SECPSignature(nativeR, s, (byte) recId);
   133→  }
   134→
   135→  /**
   136→   * Calculates an ECDH key agreement between the private and the public key.
   137→   *
   138→   * @param privKey The private key.
   139→   * @param theirPubKey The public key.
   140→   * @return The agreed secret.
   141→   */
   142→  @Override
   143→  public Bytes32 calculateECDHKeyAgreement(
   144→      final SECPPrivateKey privKey, final SECPPublicKey theirPubKey) {
   145→    checkArgument(privKey != null, "missing private key");
   146→    checkArgument(theirPubKey != null, "missing remote public key");
   147→
   148→    final ECPrivateKeyParameters privKeyP = new ECPrivateKeyParameters(privKey.getD(), curve);
   149→    final ECPublicKeyParameters pubKeyP =
   150→        new ECPublicKeyParameters(theirPubKey.asEcPoint(curve), curve);
   151→
   152→    final ECDHBasicAgreement agreement = new ECDHBasicAgreement();
   153→    agreement.init(privKeyP);
   154→    final BigInteger agreed = agreement.calculateAgreement(pubKeyP);
   155→
   156→    return UInt256.valueOf(agreed);
   157→  }
   158→
   159→  @Override
   160→  public SECPPrivateKey createPrivateKey(final BigInteger key) {
   161→    return SECPPrivateKey.create(key, ALGORITHM);
   162→  }
   163→
   164→  @Override
   165→  public SECPPrivateKey createPrivateKey(final Bytes32 key) {
   166→    return SECPPrivateKey.create(key, ALGORITHM);
   167→  }
   168→
   169→  @Override
   170→  public SECPPublicKey createPublicKey(final SECPPrivateKey privateKey) {
   171→    return SECPPublicKey.create(privateKey, curve, ALGORITHM);
   172→  }
   173→
   174→  @Override
   175→  public SECPPublicKey createPublicKey(final BigInteger key) {
   176→    return SECPPublicKey.create(key, ALGORITHM);
   177→  }
   178→
   179→  @Override
   180→  public SECPPublicKey createPublicKey(final Bytes encoded) {
   181→    return SECPPublicKey.create(encoded, ALGORITHM);
   182→  }
   183→
   184→  @Override
   185→  public ECPoint publicKeyAsEcPoint(final SECPPublicKey publicKey) {
   186→    return publicKey.asEcPoint(curve);
   187→  }
   188→
   189→  @Override
   190→  public boolean isValidPublicKey(final SECPPublicKey publicKey) {
   191→    try {
   192→      publicKeyAsEcPoint(publicKey);
   193→    } catch (IllegalArgumentException e) {
   194→      return false;
   195→    }
   196→
   197→    return true;
   198→  }
   199→
   200→  @Override
