   233→    return PROVIDER;
   234→  }
   235→
   236→  @Override
   237→  public ECDomainParameters getCurve() {
   238→    return curve;
   239→  }
   240→
   241→  /**
   242→   * Gets K calculator.
   243→   *
   244→   * @return the K Calculator
   245→   */
   246→  public abstract DSAKCalculator getKCalculator();
   247→
   248→  /**
   249→   * Decompress key ec point.
   250→   *
   251→   * @param xBN the x bn
   252→   * @param yBit the y bit
   253→   * @return the ec point
   254→   */
   255→  // Decompress a compressed public key (x co-ord and low-bit of y-coord).
   256→  protected ECPoint decompressKey(final BigInteger xBN, final boolean yBit) {
   257→    final X9IntegerConverter x9 = new X9IntegerConverter();
   258→    final byte[] compEnc = x9.integerToBytes(xBN, 1 + x9.getByteLength(curve.getCurve()));
   259→    compEnc[0] = (byte) (yBit ? 0x03 : 0x02);
   260→    // TODO: Find a better way to handle an invalid point compression here.
   261→    // Currently ECCurve#decodePoint throws an IllegalArgumentException.
   262→    return curve.getCurve().decodePoint(compEnc);
   263→  }
   264→
   265→  /**
   266→   * Given the components of a signature and a selector value, recover and return the public key
   267→   * that generated the signature according to the algorithm in SEC1v2 section 4.1.6.
   268→   *
   269→   * <p>If this method returns null it means recovery was not possible and recId should be iterated.
   270→   *
   271→   * <p>Given the above two points, a correct usage of this method is inside a for loop from 0 to 3,
   272→   * and if the output is null OR a key that is not the one you expect, you try again with the next
   273→   * recId.
   274→   *
   275→   * @param recId Which possible key to recover.
   276→   * @param r The R component of the signature.
   277→   * @param s The S component of the signature.
   278→   * @param dataHash Hash of the data that was signed.
   279→   * @return An ECKey containing only the public part, or null if recovery wasn't possible.
   280→   */
   281→  protected BigInteger recoverFromSignature(
   282→      final int recId, final BigInteger r, final BigInteger s, final Bytes32 dataHash) {
   283→    assert (recId >= 0);
   284→    assert (r.signum() >= 0);
   285→    assert (s.signum() >= 0);
   286→    assert (dataHash != null);
   287→
   288→    // 1.0 For j from 0 to h (h == recId here and the loop is outside this function)
   289→    // 1.1 Let x = r + jn
   290→    final BigInteger n = curve.getN(); // Curve order.
   291→    final BigInteger i = BigInteger.valueOf((long) recId / 2);
   292→    final BigInteger x = r.add(i.multiply(n));
   293→    // 1.2. Convert the integer x to an octet string X of length mlen using the conversion
   294→    // routine specified in Section 2.3.7, where mlen = ⌈(log2 p)/8⌉ or mlen = ⌈m/8⌉.
   295→    // 1.3. Convert the octet string (16 set binary digits)||X to an elliptic curve point R
   296→    // using the conversion routine specified in Section 2.3.4. If this conversion
   297→    // routine outputs "invalid", then do another iteration of Step 1.
   298→    //
   299→    // More concisely, what these points mean is to use X as a compressed public key.
   300→    if (x.compareTo(prime) >= 0) {
   301→      // Cannot have point co-ordinates larger than this as everything takes place modulo Q.
   302→      return null;
   303→    }
   304→    // Compressed keys require you to know an extra bit of data about the y-coord as there are
   305→    // two possibilities. So it's encoded in the recId.
   306→    final ECPoint R = decompressKey(x, (recId & 1) == 1);
   307→    // 1.4. If nR != point at infinity, then do another iteration of Step 1 (callers
   308→    // responsibility).
   309→    if (!R.multiply(n).isInfinity()) {
   310→      return null;
   311→    }
   312→    // 1.5. Compute e from M using Steps 2 and 3 of ECDSA signature verification.
   313→    final BigInteger e = dataHash.toUnsignedBigInteger();
   314→    // 1.6. For k from 1 to 2 do the following. (loop is outside this function via
   315→    // iterating recId)
   316→    // 1.6.1. Compute a candidate public key as:
   317→    // Q = mi(r) * (sR - eG)
   318→    //
   319→    // Where mi(x) is the modular multiplicative inverse. We transform this into the following:
   320→    // Q = (mi(r) * s ** R) + (mi(r) * -e ** G)
   321→    // Where -e is the modular additive inverse of e, that is z such that z + e = 0 (mod n).
   322→    // In the above equation ** is point multiplication and + is point addition (the EC group
   323→    // operator).
   324→    //
   325→    // We can find the additive inverse by subtracting e from zero then taking the mod. For
   326→    // example the additive inverse of 3 modulo 11 is 8 because 3 + 8 mod 11 = 0, and
   327→    // -3 mod 11 = 8.
   328→    final BigInteger eInv = BigInteger.ZERO.subtract(e).mod(n);
   329→    final BigInteger rInv = r.modInverse(n);
   330→    final BigInteger srInv = rInv.multiply(s).mod(n);
   331→    final BigInteger eInvrInv = rInv.multiply(eInv).mod(n);
   332→    final ECPoint q = ECAlgorithms.sumOfTwoMultiplies(curve.getG(), eInvrInv, R, srInv);
   333→
   334→    if (q.isInfinity()) {
   335→      return null;
   336→    }
   337→
   338→    final byte[] qBytes = q.getEncoded(false);
   339→    // We remove the prefix
   340→    return new BigInteger(1, Arrays.copyOfRange(qBytes, 1, qBytes.length));
   341→  }
   342→
   343→  @Override
   344→  public SECPSignature sign(final Bytes32 dataHash, final KeyPair keyPair) {
   345→    final ECDSASigner signer = new ECDSASigner(getKCalculator());
   346→
   347→    final ECPrivateKeyParameters privKey =
   348→        new ECPrivateKeyParameters(
   349→            keyPair.getPrivateKey().getEncodedBytes().toUnsignedBigInteger(), curve);
   350→    signer.init(true, privKey);
   351→
   352→    final BigInteger[] components = signer.generateSignature(dataHash.toArrayUnsafe());
   353→
   354→    return normaliseSignature(components[0], components[1], keyPair.getPublicKey(), dataHash);
   355→  }
   356→
   357→  /**
   358→   * Verifies the given ECDSA signature against the message bytes using the public key bytes.
   359→   *
   360→   * <p>When using native ECDSA verification, data must be 32 bytes, and no element may be larger
   361→   * than 520 bytes.
   362→   *
   363→   * @param data Hash of the data to verify.
   364→   * @param signature ASN.1 encoded signature.
   365→   * @param pub The public key bytes to use.
   366→   * @return True if the verification is successful.
   367→   */
   368→  @Override
   369→  public boolean verify(final Bytes data, final SECPSignature signature, final SECPPublicKey pub) {
   370→    final ECDSASigner signer = new ECDSASigner();
   371→    final Bytes toDecode = Bytes.wrap(Bytes.of((byte) 4), pub.getEncodedBytes());
   372→    final ECPublicKeyParameters params =
   373→        new ECPublicKeyParameters(curve.getCurve().decodePoint(toDecode.toArrayUnsafe()), curve);
   374→    signer.init(false, params);
   375→    try {
   376→      return signer.verifySignature(data.toArrayUnsafe(), signature.getR(), signature.getS());
   377→    } catch (final NullPointerException e) {
   378→      // Bouncy Castle contains a bug that can cause NPEs given specially crafted signatures. Those
   379→      // signatures
   380→      // are inherently invalid/attack sigs so we just fail them here rather than crash the thread.
   381→      return false;
   382→    }
   383→  }
   384→
   385→  /**
   386→   * Verifies the given ECDSA signature using the public key bytes against the message bytes,
   387→   * previously passed through a preprocessor function, which is normally a hashing function.
   388→   *
   389→   * @param data The data to verify.
   390→   * @param signature ASN.1 encoded signature.
   391→   * @param pub The public key bytes to use.
   392→   * @param preprocessor The function to apply to the data before verifying the signature, normally
   393→   *     a hashing function.
   394→   * @return True if the verification is successful.
   395→   */
   396→  @Override
   397→  public boolean verify(
   398→      final Bytes data,
   399→      final SECPSignature signature,
   400→      final SECPPublicKey pub,
   401→      final UnaryOperator<Bytes> preprocessor) {
   402→    checkArgument(preprocessor != null, "preprocessor must not be null");
   403→    return verify(preprocessor.apply(data), signature, pub);
   404→  }
   405→
   406→  @Override
   407→  public Optional<SECPPublicKey> recoverPublicKeyFromSignature(
   408→      final Bytes32 dataHash, final SECPSignature signature) {
   409→    final BigInteger publicKeyBI =
   410→        recoverFromSignature(signature.getRecId(), signature.getR(), signature.getS(), dataHash);
   411→    return publicKeyBI == null
   412→        ? Optional.empty()
   413→        : Optional.of(SECPPublicKey.create(publicKeyBI, ALGORITHM));
   414→  }
   415→
   416→  @Override
   417→  public Bytes compressPublicKey(final SECPPublicKey uncompressedPublicKey) {
   418→    return Bytes.wrap(publicKeyAsEcPoint(uncompressedPublicKey).getEncoded(true));
   419→  }
   420→}
