    32→/** The SECP256R1 implementation. */
    33→public class SECP256R1 extends AbstractSECP256 {
    34→
    35→  private static final Logger LOG = LoggerFactory.getLogger(SECP256R1.class);
    36→
    37→  /** The constant CURVE_NAME. */
    38→  public static final String CURVE_NAME = "secp256r1";
    39→
    40→  private boolean useNative;
    41→  private final LibSECP256R1 libSECP256R1 = new LibSECP256R1();
