    54→  @Override
    55→  public void disableNative() {
    56→    useNative = false;
    57→  }
    58→
    59→  @Override
    60→  public boolean isNative() {
    61→    return useNative;
    62→  }
    63→
    64→  /**
    65→   * Attempt to enable the native library for secp256r1
    66→   *
    67→   * @return true if the native library was enabled.
    68→   */
    69→  @Override
    70→  public boolean maybeEnableNative() {
    71→    try {
    72→      useNative = BesuNativeEC.ENABLED;
    73→    } catch (UnsatisfiedLinkError | NoClassDefFoundError e) {
    74→      LOG.info("Native secp256r1 not available - {}", e.getMessage());
    75→      useNative = false;
    76→    }
    77→    return useNative;
    78→  }
    79→
    80→  /**
    81→   * Check if the native library is available.
    82→   *
    83→   * @return true if the native library is available, false otherwise.
    84→   */
    85→  public static boolean isNativeAvailable() {
    86→    try {
    87→      return BesuNativeEC.ENABLED;
    88→    } catch (UnsatisfiedLinkError | NoClassDefFoundError e) {
    89→      return false;
    90→    }
    91→  }
    92→
    93→  /**
    94→   * SECP256R1 is using the non-deterministic implementation of K calculation (standard)
    95→   *
    96→   * @return an instance of RandomDSAKCalculator
    97→   */
    98→  @Override
    99→  public DSAKCalculator getKCalculator() {
   100→    return new RandomDSAKCalculator();
   101→  }
   102→
   103→  @Override
   104→  public String getCurveName() {
   105→    return CURVE_NAME;
   106→  }
   107→
   108→  @Override
   109→  public SECPSignature sign(final Bytes32 dataHash, final KeyPair keyPair) {
   110→    if (useNative) {
   111→      return signNative(dataHash, keyPair);
   112→    } else {
   113→      return super.sign(dataHash, keyPair);
   114→    }
   115→  }
   116→
   117→  @Override
   118→  public boolean verify(final Bytes data, final SECPSignature signature, final SECPPublicKey pub) {
   119→    if (useNative) {
   120→      return verifyNative(data, signature, pub, false);
   121→    } else {
   122→      return super.verify(data, signature, pub);
   123→    }
   124→  }
   125→
   126→  @Override
   127→  public boolean verifyMalleable(
   128→      final Bytes data, final SECPSignature signature, final SECPPublicKey pub) {
   129→    if (useNative) {
   130→      return verifyNative(data, signature, pub, true);
   131→    } else {
   132→      return super.verify(data, signature, pub);
   133→    }
   134→  }
   135→
   136→  @Override
   137→  public Optional<SECPPublicKey> recoverPublicKeyFromSignature(
   138→      final Bytes32 dataHash, final SECPSignature signature) {
   139→    if (useNative) {
   140→      return recoverPublicKeyFromSignatureNative(dataHash, signature);
   141→    } else {
   142→      return super.recoverPublicKeyFromSignature(dataHash, signature);
   143→    }
   144→  }
   145→
   146→  private SECPSignature signNative(final Bytes32 dataHash, final KeyPair keyPair) {
   147→    Signature nativeSignature =
   148→        libSECP256R1.sign(
   149→            dataHash.toArrayUnsafe(),
   150→            keyPair.getPrivateKey().getEncoded(),
   151→            keyPair.getPublicKey().getEncoded());
   152→
   153→    return new SECPSignature(
   154→        new BigInteger(nativeSignature.getR()),
   155→        new BigInteger(nativeSignature.getS()),
   156→        nativeSignature.getV());
   157→  }
   158→
   159→  @Override
   160→  protected BigInteger recoverFromSignature(
   161→      final int recId, final BigInteger r, final BigInteger s, final Bytes32 dataHash) {
   162→    if (useNative) {
   163→      return recoverPublicKeyFromSignatureNative(dataHash, new SECPSignature(r, s, (byte) recId))
   164→          .map(key -> new BigInteger(1, key.getEncoded()))
   165→          .orElse(null);
   166→    } else {
   167→      return super.recoverFromSignature(recId, r, s, dataHash);
   168→    }
   169→  }
   170→
   171→  private Optional<SECPPublicKey> recoverPublicKeyFromSignatureNative(
   172→      final Bytes32 dataHash, final SECPSignature signature) {
   173→    byte[] recoveredKey;
   174→
   175→    try {
   176→      recoveredKey =
   177→          libSECP256R1.keyRecovery(
   178→              dataHash.toArrayUnsafe(),
   179→              signature.getR().toByteArray(),
   180→              signature.getS().toByteArray(),
   181→              signature.getRecId());
   182→    } catch (IllegalArgumentException e) {
   183→      return Optional.empty();
   184→    }
   185→
   186→    return Optional.of(SECPPublicKey.create(Bytes.of(recoveredKey), ALGORITHM));
   187→  }
   188→
   189→  private boolean verifyNative(
   190→      final Bytes data,
   191→      final SECPSignature signature,
   192→      final SECPPublicKey pub,
   193→      final boolean allowMalleable) {
   194→
   195→    return libSECP256R1.verify(
   196→        data.toArrayUnsafe(),
   197→        signature.getR().toByteArray(),
   198→        signature.getS().toByteArray(),
   199→        pub.getEncoded(),
   200→        allowMalleable);
   201→  }
   202→}
