    34→/**
    35→ * Validator for blob transactions
    36→ *
    37→ * <p>This class enforces blob-related transaction rules, including:
    38→ *
    39→ * <ul>
    40→ *   <li>Checking that required fields are present (recipient, versioned hashes, blobs).
    41→ *   <li>Ensuring the number of blobs does not exceed the transaction gas limit cap.
    42→ *   <li>Validating versioned hashes and their supported formats.
    43→ *   <li>Verifying blob commitments against their hashes and KZG proofs.
    44→ * </ul>
    45→ *
    46→ * <p>The validator separates generic blob transaction checks from blob/commitment validation,
    47→ * ensuring clear responsibilities between transaction-level and blob-level rules.
    48→ */
    49→public class MainnetBlobsValidator {
    50→  final Set<BlobType> acceptedBlobVersions;
    51→  final GasLimitCalculator gasLimitCalculator;
    52→  final GasCalculator gasCalculator;
    53→
    54→  /**
    55→   * Creates a new {@link MainnetBlobsValidator}.
    56→   *
    57→   * @param acceptedBlobVersions the set of blob types accepted on this network
    58→   * @param gasLimitCalculator calculator for transaction blob gas caps
    59→   * @param gasCalculator calculator for gas usage of blobs
    60→   */
    61→  public MainnetBlobsValidator(
    62→      final Set<BlobType> acceptedBlobVersions,
    63→      final GasLimitCalculator gasLimitCalculator,
    64→      final GasCalculator gasCalculator) {
    65→    this.acceptedBlobVersions = acceptedBlobVersions;
    66→    this.gasLimitCalculator = gasLimitCalculator;
    67→    this.gasCalculator = gasCalculator;
    68→  }
    69→
    70→  /**
    71→   * Validates a transaction for compliance with blob-related rules.
    72→   *
    73→   * <p>Performs transaction-level validation (recipient, versioned hashes, gas cap, supported hash
    74→   * versions) and, if present, validates the blobs and commitments themselves.
    75→   *
    76→   * @param transaction the transaction to validate
    77→   * @return a {@link ValidationResult} indicating validity or the reason for rejection
    78→   */
    79→  public ValidationResult<TransactionInvalidReason> validate(final Transaction transaction) {
    80→    ValidationResult<TransactionInvalidReason> blobTransactionResult =
    81→        validateBlobTransaction(transaction);
    82→    if (!blobTransactionResult.isValid()) {
    83→      return blobTransactionResult;
    84→    }
    85→    if (transaction.getBlobsWithCommitments().isPresent()) {
    86→      return validateBlobsWithCommitments(transaction);
    87→    }
    88→    return ValidationResult.valid();
    89→  }
    90→
    91→  /**
    92→   * Validates transaction-level blob rules (independent of blob data itself).
    93→   *
    94→   * <ul>
    95→   *   <li>Blob transactions must have a recipient address.
    96→   *   <li>Versioned hashes must be present and valid.
    97→   *   <li>Blob gas cost must not exceed the configured cap.
    98→   *   <li>Only supported versioned hash IDs are accepted.
    99→   * </ul>
   100→   *
   101→   * @param transaction the blob transaction to validate
   102→   * @return a {@link ValidationResult} indicating success or reason for failure
   103→   */
   104→  private ValidationResult<TransactionInvalidReason> validateBlobTransaction(
   105→      final Transaction transaction) {
   106→
   107→    // Blob transactions must target a recipient account
   108→    if (transaction.getType().supportsBlob() && transaction.getTo().isEmpty()) {
   109→      return ValidationResult.invalid(
   110→          TransactionInvalidReason.INVALID_TRANSACTION_FORMAT,
   111→          "transaction blob transactions must have a to address");
   112→    }
   113→
   114→    // Versioned hashes must be present
   115→    if (transaction.getVersionedHashes().isEmpty()) {
   116→      return ValidationResult.invalid(
   117→          TransactionInvalidReason.INVALID_BLOBS,
   118→          "transaction blob transactions must specify one or more versioned hashes");
   119→    }
   120→
   121→    // Check blob gas cost against configured cap
   122→    final List<VersionedHash> versionedHashes = transaction.getVersionedHashes().get();
   123→    final long blobGasCost = gasCalculator.blobGasCost(versionedHashes.size());
   124→    if (blobGasCost > gasLimitCalculator.transactionBlobGasLimitCap()) {
   125→      final String error =
   126→          String.format("Blob transaction has too many blobs: %d", versionedHashes.size());
   127→      return ValidationResult.invalid(TransactionInvalidReason.TOTAL_BLOB_GAS_TOO_HIGH, error);
   128→    }
   129→
   130→    // Ensure all versioned hashes use a supported version ID
   131→    for (final VersionedHash versionedHash : versionedHashes) {
   132→      if (versionedHash.getVersionId() != VersionedHash.SHA256_VERSION_ID) {
   133→        return ValidationResult.invalid(
   134→            TransactionInvalidReason.INVALID_BLOBS,
   135→            "transaction blobs commitment version is not supported. Expected "
   136→                + VersionedHash.SHA256_VERSION_ID
   137→                + ", found "
   138→                + versionedHash.getVersionId());
   139→      }
   140→    }
   141→    return ValidationResult.valid();
   142→  }
   143→
   144→  /**
   145→   * Validates a transaction's blobs and their commitments.
   146→   *
   147→   * <ul>
   148→   *   <li>Ensures blobs and commitments are present and sizes match.
   149→   *   <li>Validates that commitment hashes match the provided versioned hashes.
   150→   *   <li>Verifies KZG proofs for all commitments.
   151→   * </ul>
   152→   *
   153→   * @param transaction the transaction containing blobs and commitments
   154→   * @return a {@link ValidationResult} indicating success or reason for failure
   155→   */
   156→  private ValidationResult<TransactionInvalidReason> validateBlobsWithCommitments(
   157→      final Transaction transaction) {
   158→
   159→    if (transaction.getBlobsWithCommitments().isEmpty()) {
   160→      return ValidationResult.invalid(
   161→          TransactionInvalidReason.INVALID_BLOBS,
   162→          "transaction blobs are empty, cannot verify without blobs");
   163→    }
   164→
   165→    BlobsWithCommitments blobsWithCommitments = transaction.getBlobsWithCommitments().get();
   166→
   167→    // Reject unsupported blob types
   168→    if (!acceptedBlobVersions.contains(blobsWithCommitments.getBlobType())) {
   169→      return ValidationResult.invalid(TransactionInvalidReason.INVALID_BLOBS, "invalid blob type");
   170→    }
   171→
   172→    // Blobs and commitments must be the same size
   173→    if (blobsWithCommitments.getBlobs().size() != blobsWithCommitments.getKzgCommitments().size()) {
   174→      return ValidationResult.invalid(
   175→          TransactionInvalidReason.INVALID_BLOBS,
   176→          "transaction blobs and commitments are not the same size");
   177→    }
   178→
   179→    if (transaction.getVersionedHashes().isEmpty()) {
   180→      return ValidationResult.invalid(
   181→          TransactionInvalidReason.INVALID_BLOBS,
   182→          "transaction versioned hashes are empty, cannot verify without versioned hashes");
   183→    }
   184→    final List<VersionedHash> versionedHashes = transaction.getVersionedHashes().get();
   185→
   186→    // Validate that each commitment matches its versioned hash
   187→    for (int i = 0; i < versionedHashes.size(); i++) {
   188→      final KZGCommitment commitment = blobsWithCommitments.getKzgCommitments().get(i);
   189→      final VersionedHash versionedHash = versionedHashes.get(i);
   190→
   191→      final VersionedHash calculatedVersionedHash = hashCommitment(commitment);
   192→      if (!calculatedVersionedHash.equals(versionedHash)) {
   193→        return ValidationResult.invalid(
   194→            TransactionInvalidReason.INVALID_BLOBS,
   195→            "transaction blobs commitment hash does not match commitment");
   196→      }
   197→    }
   198→
   199→    // Verify KZG proofs for the blobs
   200→    if (!verify4844Kzg(blobsWithCommitments)) {
   201→      return ValidationResult.invalid(
   202→          TransactionInvalidReason.INVALID_BLOBS,
   203→          "transaction blobs kzg proof verification failed");
   204→    }
   205→    return ValidationResult.valid();
   206→  }
   207→
   208→  /**
   209→   * Computes a {@link VersionedHash} from a {@link KZGCommitment}.
   210→   *
   211→   * <p>The commitment data is hashed with SHA-256 and then versioned by setting the first byte to
   212→   * {@link VersionedHash#SHA256_VERSION_ID}.
   213→   *
   214→   * @param commitment the KZG commitment to hash
   215→   * @return the corresponding {@link VersionedHash}
   216→   */
   217→  public static VersionedHash hashCommitment(final KZGCommitment commitment) {
   218→    final SHA256Digest digest = new SHA256Digest();
   219→    digest.update(commitment.getData().toArrayUnsafe(), 0, commitment.getData().size());
   220→
   221→    final byte[] dig = new byte[digest.getDigestSize()];
   222→    digest.doFinal(dig, 0);
   223→
   224→    // Prefix with supported version ID
   225→    dig[0] = VersionedHash.SHA256_VERSION_ID;
   226→    return new VersionedHash(Bytes32.wrap(dig));
   227→  }
   228→}
