    27→/** Validation rule to check if the block header's excess blob gas matches the calculated value. */
    28→public class BlobGasValidationRule implements DetachedBlockHeaderValidationRule {
    29→
    30→  private static final Logger LOG = LoggerFactory.getLogger(BlobGasValidationRule.class);
    31→
    32→  private final GasCalculator gasCalculator;
    33→  private final GasLimitCalculator gasLimitCalculator;
    34→
    35→  public BlobGasValidationRule(
    36→      final GasCalculator gasCalculator, final GasLimitCalculator gasLimitCalculator) {
    37→    this.gasCalculator = gasCalculator;
    38→    this.gasLimitCalculator = gasLimitCalculator;
    39→  }
    40→
    41→  /**
    42→   * Validates the block header by checking if the header's excess blob gas matches the calculated
    43→   * value based on the parent header, as well that the used blobGas is a multiple of GAS_PER_BLOB.
    44→   */
    45→  @Override
    46→  public boolean validate(final BlockHeader header, final BlockHeader parent) {
    47→    long headerExcessBlobGas = header.getExcessBlobGas().map(BlobGas::toLong).orElse(0L);
    48→    long parentExcessBlobGas = parent.getExcessBlobGas().map(BlobGas::toLong).orElse(0L);
    49→    long parentBlobGasUsed = parent.getBlobGasUsed().orElse(0L);
    50→
    51→    long calculatedExcessBlobGas =
    52→        gasLimitCalculator.computeExcessBlobGas(
    53→            parentExcessBlobGas, parentBlobGasUsed, parent.getBaseFee().orElse(Wei.ZERO).toLong());
    54→
    55→    if (headerExcessBlobGas != calculatedExcessBlobGas) {
    56→      LOG.info(
    57→          "Invalid block header: header excessBlobGas {} and calculated excessBlobGas {} do not match",
    58→          headerExcessBlobGas,
    59→          calculatedExcessBlobGas);
    60→      return false;
    61→    }
    62→    long headerBlobGasUsed = header.getBlobGasUsed().orElse(0L);
    63→    if (headerBlobGasUsed % gasCalculator.getBlobGasPerBlob() != 0) {
    64→      LOG.info(
    65→          "blob gas used must be multiple of GAS_PER_BLOB ({})", gasCalculator.getBlobGasPerBlob());
    66→      return false;
    67→    }
    68→    return true;
    69→  }
    70→
    71→  @Override
    72→  public String toString() {
    73→    return "BlobGasValidation";
    74→  }
    75→}
