    86→  @Override
    87→  public ValidationResult<TransactionInvalidReason> validate(
    88→      final Transaction transaction,
    89→      final Optional<Wei> baseFee,
    90→      final Optional<Wei> blobFee,
    91→      final TransactionValidationParams transactionValidationParams) {
    92→    final ValidationResult<TransactionInvalidReason> signatureResult =
    93→        validateTransactionSignature(transaction);
    94→    if (!signatureResult.isValid()) {
    95→      return signatureResult;
    96→    }
    97→
    98→    final TransactionType transactionType = transaction.getType();
    99→    if (!acceptedTransactionTypes.contains(transactionType)) {
   100→      return ValidationResult.invalid(
   101→          TransactionInvalidReason.INVALID_TRANSACTION_FORMAT,
   102→          String.format(
   103→              "Transaction type %s is invalid, accepted transaction types are %s",
   104→              transactionType, acceptedTransactionTypes));
   105→    }
   106→
   107→    if (transaction.getNonce() == MAX_NONCE) {
   108→      return ValidationResult.invalid(
   109→          TransactionInvalidReason.NONCE_OVERFLOW, "Nonce must be less than 2^64-1");
   110→    }
   111→
   112→    if (!transactionValidationParams.isAllowExceedingGasLimit()
   113→        && transaction.getGasLimit() > gasLimitCalculator.transactionGasLimitCap()) {
   114→      return ValidationResult.invalid(
   115→          TransactionInvalidReason.EXCEEDS_TRANSACTION_GAS_LIMIT,
   116→          "Transaction gas limit must be at most " + gasLimitCalculator.transactionGasLimitCap());
   117→    }
   118→
   119→    if (transactionType.supportsBlob()) {
   120→      final ValidationResult<TransactionInvalidReason> blobTransactionResult =
   121→          blobsValidator.validate(transaction);
   122→      if (!blobTransactionResult.isValid()) {
   123→        LOG.info(
   124→            "Blob transaction {} validation failed: {}",
   125→            transaction.getHash().toHexString(),
   126→            blobTransactionResult.getErrorMessage());
   127→        return blobTransactionResult;
   128→      }
   129→    }
   130→
   131→    if (transaction.isContractCreation() && transaction.getPayload().size() > maxInitcodeSize) {
   132→      return ValidationResult.invalid(
   133→          TransactionInvalidReason.INITCODE_TOO_LARGE,
   134→          String.format(
   135→              "Initcode size of %d exceeds maximum size of %s",
   136→              transaction.getPayload().size(), maxInitcodeSize));
   137→    }
   138→
   139→    if (transactionType == TransactionType.DELEGATE_CODE) {
   140→      ValidationResult<TransactionInvalidReason> codeDelegationValidation =
   141→          validateCodeDelegation(transaction);
   142→      if (!codeDelegationValidation.isValid()) {
   143→        return codeDelegationValidation;
   144→      }
   145→    }
   146→
   147→    return validateCostAndFee(transaction, baseFee, blobFee, transactionValidationParams);
   148→  }
