    34→public class BlobTransactionDecoder {
    35→  private static final Supplier<SignatureAlgorithm> SIGNATURE_ALGORITHM =
    36→      Suppliers.memoize(SignatureAlgorithmFactory::getInstance);
    37→
    38→  private BlobTransactionDecoder() {
    39→    // private constructor
    40→  }
    41→
    42→  /**
    43→   * Decodes a blob transaction from the provided RLP input.
    44→   *
    45→   * @param input the RLP input to decode
    46→   * @return the decoded transaction
    47→   */
    48→  public static Transaction decode(final Bytes input) {
    49→    Transaction transaction;
    50→    transaction = readTransactionPayload(input);
    51→    return transaction;
    52→  }
    53→
    54→  private static Transaction readTransactionPayload(final Bytes input) {
    55→    final Transaction.Builder builder = Transaction.builder();
    56→    final RLPInput txRlp = RLP.input(input.slice(1)); // Skip the transaction type byte
    57→    builder.sizeForBlockInclusion(input.size()).hash(Hash.hash(input));
    58→    // blob tx without blobs cannot be announced, so sizeForAnnouncement is not set
    59→    readTransactionPayloadInner(builder, txRlp);
    60→    return builder.build();
    61→  }
    62→
    63→  /**
    64→   * Reads the payload of a blob transaction from the provided RLP input.
    65→   *
    66→   * <p>[chain_id, nonce, max_priority_fee_per_gas, max_fee_per_gas, gas_limit, to, value, data,
    67→   * access_list, max_fee_per_blob_gas, blob_versioned_hashes, y_parity, r, s]
    68→   *
    69→   * @param builder the transaction builder
    70→   * @param input the RLP input to read from
    71→   */
    72→  static void readTransactionPayloadInner(final Transaction.Builder builder, final RLPInput input) {
    73→    input.enterList();
    74→    builder
    75→        .type(TransactionType.BLOB)
    76→        .chainId(input.readBigIntegerScalar())
    77→        .nonce(input.readLongScalar())
    78→        .maxPriorityFeePerGas(Wei.of(input.readUInt256Scalar()))
    79→        .maxFeePerGas(Wei.of(input.readUInt256Scalar()))
    80→        .gasLimit(input.readLongScalar())
    81→        .to(input.readBytes(v -> v.isEmpty() ? null : Address.wrap(v)))
    82→        .value(Wei.of(input.readUInt256Scalar()))
    83→        .payload(input.readBytes())
    84→        .accessList(
    85→            input.readList(
    86→                accessListEntryRLPInput -> {
    87→                  accessListEntryRLPInput.enterList();
    88→                  final AccessListEntry accessListEntry =
    89→                      new AccessListEntry(
    90→                          Address.wrap(accessListEntryRLPInput.readBytes()),
    91→                          accessListEntryRLPInput.readList(RLPInput::readBytes32));
    92→                  accessListEntryRLPInput.leaveList();
    93→                  return accessListEntry;
    94→                }))
    95→        .maxFeePerBlobGas(Wei.of(input.readUInt256Scalar()))
    96→        .versionedHashes(
    97→            input.readList(versionedHashes -> new VersionedHash(versionedHashes.readBytes32())));
    98→
    99→    final byte recId = (byte) input.readUnsignedByteScalar();
   100→    builder.signature(
   101→        SIGNATURE_ALGORITHM
   102→            .get()
   103→            .createSignature(
   104→                input.readUInt256Scalar().toUnsignedBigInteger(),
   105→                input.readUInt256Scalar().toUnsignedBigInteger(),
   106→                recId));
   107→    input.leaveList();
   108→  }
   109→}
